package com.phoenix.business.web;import com.phoenix.business.domain.Member;import com.phoenix.business.repository.*;import lombok.RequiredArgsConstructor;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.*;
@RestController @RequestMapping("/api/dashboard") @RequiredArgsConstructor public class DashboardController {private final MemberRepository members;private final PaymentRepository payments;private final AttendanceRepository attendance;@GetMapping public Map<String,Object> get(){LocalDate today=LocalDate.now(),month=today.withDayOfMonth(1);Instant ds=today.atStartOfDay(ZoneOffset.UTC).toInstant(),de=today.plusDays(1).atStartOfDay(ZoneOffset.UTC).toInstant(),ms=month.atStartOfDay(ZoneOffset.UTC).toInstant();Map<String,Object> m=new LinkedHashMap<>();m.put("activeMembers",members.countByStatus(Member.Status.ACTIVE));m.put("expiredMembers",members.countByStatus(Member.Status.EXPIRED));m.put("expiringSoon",members.countByExpiryDateBetween(today,today.plusDays(7)));m.put("todayAttendance",attendance.countByCheckedInAtBetween(ds,de));m.put("todayRevenue",payments.revenue(ds,de));m.put("monthRevenue",payments.revenue(ms,de));m.put("newMembersThisMonth",members.countByJoinDateBetween(month,today));m.put("renewalsThisMonth",payments.countByPaymentDateBetween(ms,de));m.put("recentPayments",payments.findTop10ByOrderByPaymentDateDesc());m.put("monthlyRevenue",monthlyRevenue(today));m.put("attendanceTrend",attendanceTrend(today));m.put("membershipDistribution",members.membershipDistribution().stream().map(x->Map.of("label",x[0],"value",x[1])).toList());return m;}private List<Map<String,Object>> monthlyRevenue(LocalDate today){List<Map<String,Object>> out=new ArrayList<>();for(int i=5;i>=0;i--){LocalDate a=today.withDayOfMonth(1).minusMonths(i),b=a.plusMonths(1);out.add(Map.of("label",a.getMonth().toString().substring(0,3),"value",payments.revenue(a.atStartOfDay(ZoneOffset.UTC).toInstant(),b.atStartOfDay(ZoneOffset.UTC).toInstant())));}return out;}private List<Map<String,Object>> attendanceTrend(LocalDate today){Instant a=today.minusDays(6).atStartOfDay(ZoneOffset.UTC).toInstant(),b=today.plusDays(1).atStartOfDay(ZoneOffset.UTC).toInstant();Map<LocalDate,Long> counts=attendance.findByCheckedInAtBetween(a,b).stream().collect(java.util.stream.Collectors.groupingBy(x->x.getCheckedInAt().atZone(ZoneOffset.UTC).toLocalDate(),java.util.stream.Collectors.counting()));List<Map<String,Object>> out=new ArrayList<>();for(int i=6;i>=0;i--){LocalDate d=today.minusDays(i);out.add(Map.of("label",d.getDayOfWeek().toString().substring(0,3),"value",counts.getOrDefault(d,0L)));}return out;}}
